con.execute("""CREATE TABLE emp_m AS
WITH s AS (SELECT employee_id, any_value(location_id) loc, sum(gross_price*quantity) gross, count(DISTINCT (dt,location_id,check_id)) n_chk, count(DISTINCT dt) n_days FROM items WHERE employee_id<>0 GROUP BY 1),
v AS (SELECT employee_id, sum(amount) void_amt, count(*) n_void FROM voids GROUP BY 1),
d AS (SELECT employee_id, sum(amount) disc_amt, count(*) FILTER (WHERE discount_name='WALKOUT') n_walk FROM (SELECT employee_id, amount, discount_name FROM item_discounts UNION ALL SELECT employee_id, amount, discount_name FROM check_discounts) GROUP BY 1),
p AS (SELECT employee_id, sum(amount) FILTER (WHERE pay_cat_name='CASH') cash, sum(amount) pay, sum(-gratuity) tips FROM payments GROUP BY 1)
SELECT s.*, coalesce(void_amt,0) void_amt, coalesce(n_void,0) n_void, coalesce(disc_amt,0) disc_amt, coalesce(n_walk,0) n_walk, coalesce(cash,0) cash, coalesce(pay,0) pay, coalesce(tips,0) tips,
 coalesce(void_amt,0)/nullif(gross,0) void_rate, coalesce(disc_amt,0)/nullif(gross,0) disc_rate, coalesce(cash,0)/nullif(pay,0) cash_share FROM s LEFT JOIN v USING (employee_id) LEFT JOIN d USING (employee_id) LEFT JOIN p USING (employee_id)""")
show("emp universe", "SELECT count(*) n, count(*) FILTER (WHERE gross>=5000) n_active5k, approx_quantile(gross,[0.25,0.5,0.75]) gross_q, approx_quantile(n_days,[0.5]) days_med FROM emp_m")
show("emp rate distribution (gross>=5k)", """SELECT approx_quantile(void_rate,[0.5,0.9,0.99]) void_q, max(void_rate) void_max, approx_quantile(disc_rate,[0.5,0.9,0.99]) disc_q, max(disc_rate) disc_max, approx_quantile(cash_share,[0.5,0.9,0.99]) cash_q, approx_quantile(n_walk,[0.5,0.9,0.99]) walk_q, max(n_walk) walk_max FROM emp_m WHERE gross>=5000""")
show("concentration: share of total $ from top 1%/5% of employees", """WITH v AS (SELECT void_amt x, row_number() OVER (ORDER BY void_amt DESC) r, count(*) OVER () n FROM emp_m), d AS (SELECT disc_amt x, row_number() OVER (ORDER BY disc_amt DESC) r, count(*) OVER () n FROM emp_m), w AS (SELECT n_walk x, row_number() OVER (ORDER BY n_walk DESC) r, count(*) OVER () n FROM emp_m)
 SELECT 'void' m, round(sum(x) FILTER (WHERE r<=n*0.01)/sum(x),3) top1, round(sum(x) FILTER (WHERE r<=n*0.05)/sum(x),3) top5 FROM v UNION ALL SELECT 'disc', round(sum(x) FILTER (WHERE r<=n*0.01)/sum(x),3), round(sum(x) FILTER (WHERE r<=n*0.05)/sum(x),3) FROM d UNION ALL SELECT 'walkouts', round(sum(x) FILTER (WHERE r<=n*0.01)/sum(x),3), round(sum(x) FILTER (WHERE r<=n*0.05)/sum(x),3) FROM w""")
show("top 8 employees by void rate (gross>=10k)", "SELECT employee_id, loc, round(gross) gross, n_void, round(void_rate*100,2) void_pct, round(disc_rate*100,2) disc_pct, n_walk, round(cash_share*100,1) cash_pct FROM emp_m WHERE gross>=10000 ORDER BY void_rate DESC LIMIT 8")
show("manager approvals", """WITH a AS (SELECT manager_id, employee_id, amount FROM voids UNION ALL SELECT manager_id, employee_id, amount FROM item_discounts UNION ALL SELECT manager_id, employee_id, amount FROM check_discounts)
 SELECT count(DISTINCT manager_id) n_mgr, count(*) FILTER (WHERE manager_id=employee_id) self_n, round(sum(amount) FILTER (WHERE manager_id=employee_id)) self_amt, count(*) FILTER (WHERE manager_id IS NULL OR manager_id=0) no_mgr_n FROM a""")
con.execute("""CREATE TABLE loc_m AS SELECT location_id, count(*) n_chk, sum(gross_ext) gross, sum(void_amt)/sum(gross_ext) void_rate, sum(cdisc+idisc)/sum(gross_ext) disc_rate, avg((gross_ext>0 AND sold-cdisc<=0.005)::INT) comp_chk_rate FROM ck GROUP BY 1""")
con.execute("""CREATE TABLE loc_c AS SELECT location_id, sum(amount) FILTER (WHERE pay_cat_name='CASH')/sum(amount) cash_share, count(*) FILTER (WHERE amount<0) neg_pay FROM payments GROUP BY 1""")
show("store spread (127 stores)", """SELECT round(min(void_rate)*100,2) v_min, round(median(void_rate)*100,2) v_med, round(max(void_rate)*100,2) v_max, round(min(disc_rate)*100,2) d_min, round(median(disc_rate)*100,2) d_med, round(max(disc_rate)*100,2) d_max,
 round(min(cash_share)*100,1) c_min, round(median(cash_share)*100,1) c_med, round(max(cash_share)*100,1) c_max, round(median(comp_chk_rate)*100,2) comp_med, round(max(comp_chk_rate)*100,2) comp_max FROM loc_m JOIN loc_c USING (location_id)""")
con.execute("COPY emp_m TO '"+P+'/emp_metrics.parquet'+"'")
